        r#"{"type":"progress","step":"inspect","detail":"scene"}"#,
    ).expect("semantic event");
    assert!(matches!(
        event,
        ProviderAgentEvent::Progress { step, detail } if step == "inspect" && detail == "scene"
    ));
}

